<script setup>
import {inject,computed,ref,onMounted,nextTick} from 'vue';
import ProductCard from '../ProductCard.vue';
import SettingsIcon from '../SettingsIcon.vue';
import {categories,size} from '../../lib/catalog';
const {form,frozen,uploadFiles,editStep,zipEnabled}=inject('productWizard');const heading=ref();
const item=computed(()=>({id:'__wizard-preview',name:form.name,category:form.category,tags:[...form.avatars.map(a=>'avatar:'+a),...(form.generic?['compatibilidad:generico']:[]),...(form.adult||form.category==='09_R18'?['contenido:r18']:[]),...form.tags.map(t=>'tag:'+t)],avatars:form.avatars,generic:form.generic,adult:form.adult||form.category==='09_R18',images:[],files:[],size:uploadFiles.value.reduce((sum,f)=>sum+f.size,0)}));
const fileType=file=>file.name.includes(".")?file.name.split(".").pop().toUpperCase():"Archivo";
onMounted(async()=>{await nextTick();heading.value?.focus();});
</script>
<template><section class="wizard-step-summary"><div class="wizard-summary-preview"><span ref="heading" tabindex="-1" class="wizard-sr-only">Resumen del producto</span><ProductCard :item="item" :cover-url="form.previewUrl" :favorite="false" show-type/></div><div class="wizard-summary-blocks"><section class="wizard-summary-block"><header><h4>DETALLES</h4><button type="button" :disabled="frozen" @click="editStep(2)">Editar</button></header><dl><dt>Nombre</dt><dd>{{form.name}}</dd><dt>Categoría</dt><dd>{{categories[form.category]}}</dd><dt>R18</dt><dd>{{item.adult?'Sí':'No'}}</dd></dl></section><section class="wizard-summary-block"><header><h4>COMPATIBILIDAD</h4><button type="button" :disabled="frozen" @click="editStep(3)">Editar</button></header><dl><dt>Avatares</dt><dd><template v-if="form.generic">Todos (genérico)</template><template v-else-if="form.avatars.length"><span v-for="avatar in form.avatars" :key="avatar" class="wizard-summary-chip">{{avatar}}</span></template><template v-else>—</template></dd><dt>Tags</dt><dd><span v-for="tag in form.tags" :key="tag" class="wizard-summary-chip outline">#{{tag}}</span><template v-if="!form.tags.length">—</template></dd></dl></section></div><section class="wizard-summary-block wizard-files-table-block"><header><h4>ARCHIVOS · {{form.files.length}}</h4><button type="button" :disabled="frozen" @click="editStep(1)">Editar</button></header><p v-if="zipEnabled" class="wizard-zip-note">Se guardarán en un ZIP. La portada queda al lado.</p><div class="wizard-files-table-scroll"><table class="wizard-files-table"><thead><tr><th scope="col">Archivo</th><th scope="col">Tipo</th><th scope="col">Tamaño</th></tr></thead><tbody><tr v-for="file in form.files" :key="file.name"><td><div><SettingsIcon :name="/\.(png|jpe?g|webp)$/i.test(file.name)?'image':/\.(zip|rar|7z|unitypackage)$/i.test(file.name)?'archive':'file'"/><span :title="file.name">{{file.name}}</span></div></td><td>{{fileType(file)}}</td><td>{{size(file.size)}}</td></tr></tbody><tfoot><tr><th scope="row" colspan="2">Total · {{form.files.length}} archivos</th><td>{{size(form.files.reduce((sum,file)=>sum+file.size,0))}}</td></tr></tfoot></table></div></section></section></template>

